SET NAMES utf8mb4;
SELECT 'competition_entries' check_item, COUNT(*) value FROM beer_entry WHERE competition_id = 1070 AND deleted_flag = 0;
SELECT 'target_entries' check_item, COUNT(DISTINCT e.id) value FROM beer_entry e JOIN entry_scan_label l ON l.beer_entry_id=e.id WHERE e.competition_id=1070 AND e.deleted_flag=0 AND l.competition_id=1070 AND l.short_code IN (CONVERT(0x3038393138 USING utf8mb4),CONVERT(0x3133303237 USING utf8mb4),CONVERT(0x3035313237 USING utf8mb4),CONVERT(0x3332323232 USING utf8mb4),CONVERT(0x3332323233 USING utf8mb4),CONVERT(0x3132323131 USING utf8mb4),CONVERT(0x3132323132 USING utf8mb4),CONVERT(0x3132323133 USING utf8mb4),CONVERT(0x3132323134 USING utf8mb4),CONVERT(0x3332373539 USING utf8mb4));
SELECT 'new_entries' check_item, COUNT(DISTINCT e.id) value FROM beer_entry e JOIN entry_scan_label l ON l.beer_entry_id=e.id WHERE e.competition_id=1070 AND e.deleted_flag=0 AND l.competition_id=1070 AND l.short_code IN (CONVERT(0x3332323232 USING utf8mb4),CONVERT(0x3332323233 USING utf8mb4),CONVERT(0x3132323131 USING utf8mb4),CONVERT(0x3132323132 USING utf8mb4),CONVERT(0x3132323133 USING utf8mb4),CONVERT(0x3132323134 USING utf8mb4),CONVERT(0x3332373539 USING utf8mb4));
SELECT 'short_code_duplicates' check_item, COUNT(*) value FROM (SELECT short_code FROM entry_scan_label GROUP BY short_code HAVING COUNT(*)>1) d;
SELECT 'active_label_missing' check_item, COUNT(*) value FROM beer_entry e LEFT JOIN entry_scan_label l ON l.beer_entry_id=e.id AND l.status='ACTIVE' WHERE e.competition_id=1070 AND e.deleted_flag=0 AND l.id IS NULL;
SELECT 'extra_field_missing' check_item, COUNT(*) value FROM (SELECT e.id FROM beer_entry e JOIN entry_scan_label l ON l.beer_entry_id=e.id LEFT JOIN beer_entry_extra_field x ON x.beer_entry_id=e.id WHERE e.competition_id=1070 AND e.deleted_flag=0 AND l.competition_id=1070 AND l.short_code IN (CONVERT(0x3332323232 USING utf8mb4),CONVERT(0x3332323233 USING utf8mb4),CONVERT(0x3132323131 USING utf8mb4),CONVERT(0x3132323132 USING utf8mb4),CONVERT(0x3132323133 USING utf8mb4),CONVERT(0x3132323134 USING utf8mb4),CONVERT(0x3332373539 USING utf8mb4)) GROUP BY e.id HAVING COUNT(x.id)=0) missing;
SELECT l.short_code,e.name,b.company_name,b.contact_name,b.phone,pa.phone account_phone,e.style,e.abv,JSON_UNQUOTE(JSON_EXTRACT(e.extra_fields_json,'$.specialIngredients')) special_ingredients,JSON_UNQUOTE(JSON_EXTRACT(e.extra_fields_json,'$.custom_1785549677921_0089y')) promotion FROM beer_entry e JOIN brewery b ON b.id=e.brewery_id JOIN entry_scan_label l ON l.beer_entry_id=e.id LEFT JOIN portal_account pa ON pa.brewery_id=b.id WHERE e.competition_id=1070 AND e.deleted_flag=0 AND l.competition_id=1070 AND l.short_code IN (CONVERT(0x3038393138 USING utf8mb4),CONVERT(0x3133303237 USING utf8mb4),CONVERT(0x3035313237 USING utf8mb4),CONVERT(0x3332323232 USING utf8mb4),CONVERT(0x3332323233 USING utf8mb4),CONVERT(0x3132323131 USING utf8mb4),CONVERT(0x3132323132 USING utf8mb4),CONVERT(0x3132323133 USING utf8mb4),CONVERT(0x3132323134 USING utf8mb4),CONVERT(0x3332373539 USING utf8mb4)) ORDER BY l.short_code,pa.phone;
SELECT x.field_key,COUNT(*) value FROM beer_entry_extra_field x JOIN beer_entry e ON e.id=x.beer_entry_id WHERE e.competition_id=1070 AND e.deleted_flag=0 GROUP BY x.field_key ORDER BY x.field_key;
